#include <iostream>

class Base {
public:
    virtual void print() { std::cout << "Base"; }
};

class Derived : public Base {
public:
    void print() { std::cout << "Derived"; }
};

int main() {
    Base* obj = new Derived();
    obj->print();
    delete obj;
    return 0;
}

