#include <iostream>

class Base {
public:
    virtual void show() { std::cout << "B"; }
};

class Derived : public Base {
public:
    void show() override { std::cout << "D"; }
};

void display(Base obj) {
    obj.show();
}

int main() {
    Derived d;
    display(d);
    return 0;
}
